import * as React from 'react';
import PropTypes from 'prop-types';
// @mui
import {  
  Box,
  Modal,
  Button,
  Stack,
  TextField

} from '@mui/material';



const style = {
  position: 'absolute',
  top: '50%',
  left: '50%',
  transform: 'translate(-50%, -50%)',
  width: '50vw',
  height: '50vh',
  '@media screen and (max-width: 600px)': {
    width: '50vw', // Width de 100% para telas de celulares
    height: '50vh',
  },
  bgcolor: 'background.paper',
  border: '2px solid #000',
  boxShadow: 24,
  p: 2,
  display: 'flex',
  flexDirection: 'column',
  overflowY: 'auto',
  backgroundColor: 'azure',
  alignItems: 'center',
  justifyContent: 'center'
};

// ----------------------------------------------------------------------

// eslint-disable-next-line no-unused-vars
const ModalAddAgendamento = React.forwardRef((props, ref) => {
  const [telefone, setTelefone] = React.useState(null)

  const handleConfirm = () => {
    if(telefone){
      props.promise.resolve(telefone)
    }else{
      window.alert('Informe o nome')
    }
  }
  
  return (


    <Modal
      open={props.open}
      onClose={props.onClose}
      aria-labelledby="modal-modal-title"
      aria-describedby="modal-modal-description"
      >
        <Box sx={style}>
          <p>{props.title}</p>
          <TextField id={"agendamento"} label="Nome" variant="outlined" value={telefone} onChange={(e) => setTelefone(e.target.value)}/>
          <Stack direction={'row'} justifyContent={'space-between'} gap={20} mt={5}>
            <Button variant="outlined" color="error" onClick={() => props.promise.reject(new Error(false))}>
              Cancelar
            </Button>
            <Button variant="contained" color="success" onClick={handleConfirm}>
              Confirmar
            </Button>
          </Stack>
          
        </Box> 
    </Modal> 
  );
})

ModalAddAgendamento.propTypes = {
  open: PropTypes.bool,
  onClose: PropTypes.func,
  onConfirm: PropTypes.func,
  onCancel: PropTypes.func
}

export default (ModalAddAgendamento);