  const listClientes2 = applySortFilter(listClientes, getComparator(order, orderBy), filterName, filterId);
  

  function getComparator(order, orderBy) {
    return order === 'desc'
      ? (a, b) => descendingComparator(a, b, orderBy)
      : (a, b) => -descendingComparator(a, b, orderBy);
  }


  function applySortFilter(array, comparator, filterName, filterId) {
    const stabilizedThis = array.map((el, index) => [el, index]);
    stabilizedThis.sort((a, b) => {
      const order = comparator(a[0], b[0]);
      if (order !== 0) return order;
      return a[1] - b[1];
    });

    if (filterName) {
      return filter(array, (_user) => _user.nome &&  _user.nome.toLowerCase().indexOf(filterName.toLowerCase()) !== -1 );
    }

    // parseInt(cliente.cliente, 10) === parseInt(filterId, 10)
    if (filterId) {
      return array.filter((cliente) => Number(cliente.cliente) === Number(filterId));
    }

    return stabilizedThis.map((el) => el[0]);
  }

  function descendingComparator(a, b, orderBy) {
    if (b[orderBy] < a[orderBy]) {
      return -1;
    }
    if (b[orderBy] > a[orderBy]) {
      return 1;
    }
    return 0;
  }

